# Envoyer l'email d'annonce portail aux abonnements sélectionnés
if records:
    template = env.ref('lolirine_email_templates.email_template_annonce_portail_subscription', raise_if_not_found=False)
    if template:
        for record in records:
            if record.partner_id and record.partner_id.email:
                template.send_mail(record.id, force_send=False)

        # Message de confirmation
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Emails programmés',
                'message': f'{len(records)} email(s) d\'annonce portail ont été mis en file d\'attente.',
                'type': 'success',
                'sticky': False,
            }
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Erreur',
                'message': 'Template d\'email non trouvé. Veuillez réinstaller le module.',
                'type': 'danger',
                'sticky': True,
            }
        }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Attention',
            'message': 'Veuillez sélectionner au moins un abonnement.',
            'type': 'warning',
            'sticky': False,
        }
    }

# Envoyer l'email d'annonce portail aux contacts sélectionnés
if records:
    template = env.ref('lolirine_email_templates.email_template_annonce_portail_partner', raise_if_not_found=False)
    if template:
        sent_count = 0
        skipped_count = 0
        for record in records:
            if record.email:
                template.send_mail(record.id, force_send=False)
                sent_count += 1
            else:
                skipped_count += 1

        # Message de confirmation
        message = f'{sent_count} email(s) d\'annonce portail ont été mis en file d\'attente.'
        if skipped_count > 0:
            message += f' {skipped_count} contact(s) ignoré(s) (pas d\'email).'

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Emails programmés',
                'message': message,
                'type': 'success',
                'sticky': False,
            }
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Erreur',
                'message': 'Template d\'email non trouvé. Veuillez réinstaller le module.',
                'type': 'danger',
                'sticky': True,
            }
        }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Attention',
            'message': 'Veuillez sélectionner au moins un contact.',
            'type': 'warning',
            'sticky': False,
        }
    }
